   ウォレットに出ず「届いていない」ように見えていた（10/28、証明書を
   手で1枚ずつ「NFTをインポート」して、やっと見えた）。
   受け取ったあとと、受け取り済みの証明書に、届いた先のアドレスと
   「MetaMaskに追加」（コントラクトとトークン ID を入れた状態で開く）を出す。

   受け取りの宛先を決めるのはサーバー（連携済みのウォレット）。
   ここで window.ethereum を使うのは、追加の画面を開くときだけ。 */
function _spNftAddr(a) {
  a = String(a || '');
  return /^0x[0-9a-fA-F]{40}$/.test(a) ? a.slice(0, 6) + '…' + a.slice(-4) : '';
}
/* label が空なら「〇〇 に届きました」だけを出す（受け取った直後用）。 */
function _spMintedHtml(label, wallet, tokenIds, contract) {
  const to = _spNftAddr(wallet);
  const ids = (tokenIds || []).map(String).filter(function (t) { return /^\d+$/.test(t); });
  const c = /^0x[0-9a-fA-F]{40}$/.test(String(contract || '')) ? String(contract) : '';
  const text = label ? '✓ ' + label + (to ? '（' + to + ' に届きました）' : '') : (to ? to + ' に届きました' : '');
  let html = text ? '<br><small class="spp-minted">' + escapeHtml(text) + '</small>' : '';
  if (ids.length && c)
    html += '<br><button type="button" class="spp-star-claim" data-watch-nft="' + escapeHtml(ids.join(','))
      + '" data-watch-contract="' + escapeHtml(c) + '" data-watch-wallet="'
      + escapeHtml(String(wallet || '').toLowerCase()) + '">MetaMaskに追加</button>';
