}
/* 自分の証明書。読めなければ null（そのときは「受け取る」を出したままにする）。 */
async function _spMyCertificates() {
  try {
    const r = await fetch('https://emu-realtime.onrender.com/api/schoolpark/quest-completions/certificates/mine',
      { headers: await emuAuthHeaders(false) });
    if (!r.ok) return null;
