  } catch (e) { return null; }
}
/* そのクエストの周回が全部受け取り済みなら、その欄を返す。まだ残りがあれば空。 */
function _spCertMintedHtml(certs, questId, rounds) {
  if (!certs || !Array.isArray(certs.certificates)) return '';
  const mine = certs.certificates.filter(function (c) {
    return c && c.questId === questId && c.minted && /^\d+$/.test(String(c.tokenId || ''));
  }).sort(function (a, b) { return (Number(a.round) || 1) - (Number(b.round) || 1); });
  if (!mine.length || mine.length < Math.max(1, Number(rounds) || 1)) return '';
  return _spMintedHtml('証明書NFTを受け取り済み', mine[mine.length - 1].wallet,
    mine.map(function (c) { return c.tokenId; }), certs.contract);
}
