async function spWatchNft(button) {
  if (!button || button.disabled) return;
  const contract = String(button.dataset.watchContract || '');
  const ids = String(button.dataset.watchNft || '').split(',').filter(function (t) { return /^\d+$/.test(t); });
  const wallet = String(button.dataset.watchWallet || '').toLowerCase();
  const manual = '\n\nMetaMask の「NFTをインポート」で、次を入れても追加できます（ネットワークは Polygon）。'
    + '\nアドレス：' + contract + '\nトークンID：' + ids.join('、');
  if (!window.ethereum || typeof window.ethereum.request !== 'function') {
    alert('MetaMask が見つかりませんでした。' + manual);
    return;
  }
  const before = button.textContent;
  button.disabled = true;
  button.textContent = 'MetaMaskで確認…';
  try {
    /* 届いた先と違うアカウントを開いていると、MetaMask は「持ち主ではない」で断る。
       先にこちらで分かる言葉にする。 */
    const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
    const now = String((accounts || [])[0] || '').toLowerCase();
    if (wallet && now && now !== wallet)
      throw new Error('このNFTは ' + _spNftAddr(wallet) + ' に届いています。いま MetaMask で開いているのは '
        + _spNftAddr(now) + ' です。\nMetaMask で届いた先のアカウントに切り替えてから、もう一度押してください。');
    if ((await window.ethereum.request({ method: 'eth_chainId' })) !== '0x89')
      await window.ethereum.request({ method: 'wallet_switchEthereumChain', params: [{ chainId: '0x89' }] });
    for (const id of ids) {
      try {
        await window.ethereum.request({ method: 'wallet_watchAsset',
          params: { type: 'ERC721', options: { address: contract, tokenId: id } } });
      } catch (e) {
        if (e && e.code === 4001) throw e;                            /* 断った */
        if (/already/i.test(String(e && e.message || ''))) continue;   /* もう出ている */
        throw e;
      }
    }
    button.textContent = '✓ MetaMaskに追加しました';
  } catch (e) {
    button.disabled = false;
    button.textContent = before;
    if (e && e.code === 4001) return;
    alert((e && e.message ? e.message : 'MetaMask に追加できませんでした。') + manual);
  }
}
