const state={posts:[],totalCount:null,filter:'new',theme:'すべて',query:'',account:'',imageUrl:'',composeTheme:'経験',monthlyTheme:'はじめる',monthlyCopy:'',titleBeforeLock:'',drafts:[],scheduledCount:0,helpedCount:0,conclusions:[],canDraft:false,canSchedule:false,hasMore:false,guestCapped:false,guestLimit:0,pending:null,lastFocus:null,authors:{},editingDraftId:'',panelDrafts:[]};
