function resetComposer(){composeForm.reset();state.imageUrl='';state.editingDraftId='';$('#editingDraftNote').hidden=true;state.composeTheme='経験';state.titleBeforeLock='';$('#preview').style.display='none';themeButtons();lockTitleForMonthly()}
function resetComposer(){composeForm.reset();state.imageUrl='';state.composeTheme='経験';state.titleBeforeLock='';$('#preview').style.display='none';themeButtons();lockTitleForMonthly()}
function openComposer(){openOverlay($('#composer'))}function payload(){return{title:$('#title').value.trim(),body:$('#body').value.trim(),tags:[state.composeTheme,$('#tags').value].filter(Boolean).join(','),imageUrl:state.imageUrl,...(state.editingDraftId?{draftId:state.editingDraftId}:{})}}
function request(kind){if(!$('#composeForm').reportValidity())return;const requestId=crypto.randomUUID?crypto.randomUUID():String(Date.now());state.pending={requestId,kind,updating:!!state.editingDraftId};setBusy(true);const type=kind==='publish'?'emu-knowledge-publish':kind==='draft'?'emu-knowledge-draft':'emu-knowledge-schedule',data=payload();if(kind==='schedule'){if(!$('#scheduledAt').value)return finish(false,emuT('k.toast.needSchedule'));data.scheduledAt=$('#scheduledAt').value}send({type,requestId,payload:data});notify(kind==='publish'?emuT('k.toast.publishing'):kind==='draft'?emuT('k.toast.saving'):emuT('k.toast.scheduling'))}
function finish(ok,error){setBusy(false);if(ok){closeOverlay($('#composer'));resetComposer();notify(state.pending?.kind==='draft'?emuT(state.pending.updating?'k.toast.draftUpdated':'k.toast.draftSaved'):state.pending?.kind==='schedule'?emuT('k.toast.scheduled'):emuT('k.toast.published'))}else notify(error||emuT('k.toast.failed'));state.pending=null}
