/* 下書きを開き直す。題名・本文・タグ・画像を入れて投稿の画面を開く。
   投稿・予約するとこの下書きは消え、もう一度「下書き」を押すと同じ下書きを上書きする。 */
function editDraft(id){const d=(state.panelDrafts||[]).find(x=>String(x.id)===String(id));if(!d)return;
  closeOverlay($('#panel'));resetComposer();
  const list=tags(d),mt=state.monthlyTheme||'',themes=THEMES.slice(1).concat(mt?[mt]:[]);
  if(list.length&&themes.includes(list[0]))state.composeTheme=list.shift();
  themeButtons();lockTitleForMonthly();
  if($('#title').readOnly)state.titleBeforeLock=String(d.title||'');else $('#title').value=String(d.title||'');
  $('#body').value=String(d.body||'');$('#tags').value=list.join(',');
  state.imageUrl=String(d.imageUrl||'');if(state.imageUrl){$('#preview').src=state.imageUrl;$('#preview').style.display='block'}
  state.editingDraftId=String(d.id);const note=$('#editingDraftNote');note.textContent=emuT('k.editingDraft');note.hidden=false;
  openComposer()}
function renderPanel(kind,items){if(kind==='library'){const posts=items.posts||[],drafts=items.drafts||[];state.panelDrafts=drafts;$('#panelList').innerHTML=`<h3>${esc(emuT('k.panel.myPosts'))}</h3>${posts.length?posts.map(p=>`<article class="list-item"><b>${esc(p.title)}</b><small> Good ${p.goodCount||0}・Change ${p.changeCount||0}</small></article>`).join(''):`<p>${esc(emuT('k.panel.noPosts'))}</p>`}<h3>${esc(emuT('k.panel.drafts'))}</h3>${drafts.length?drafts.map(d=>`<article class="list-item"><b>${esc(d.title)}</b><p>${esc(String(d.body||'').slice(0,100))}</p><div class="draft-actions"><button data-edit-draft="${esc(d.id)}">${esc(emuT('k.panel.edit'))}</button><button data-delete-draft="${esc(d.id)}">${esc(emuT('k.panel.delete'))}</button></div></article>`).join(''):`<p>${esc(emuT('k.panel.noDrafts'))}</p>`}`;document.querySelectorAll('[data-edit-draft]').forEach(b=>b.onclick=()=>editDraft(b.dataset.editDraft));document.querySelectorAll('[data-delete-draft]').forEach(b=>b.onclick=()=>send({type:'emu-knowledge-delete-draft',draftId:b.dataset.deleteDraft}))}else{const rows=Array.isArray(items)?items:[];$('#panelList').innerHTML=rows.length?rows.map((row,i)=>`<article class="list-item"><b>${i+1}. ${esc(row.displayName||row.address||emuT('k.anonymous'))}</b><small>${esc(row.scoreLabel||String(row.score||0))}</small></article>`).join(''):`<p>${esc(emuT('k.panel.noRanking'))}</p>`}}
