window.addEventListener('message',e=>{if(e.origin!==ORIGIN||e.source!==parent)return;const m=e.data||{};if(m.type==='emu-knowledge-filter'){const map={recommended:'recommended',recommend:'recommended',trend:'monthly',monthly:'monthly',new:'new',good:'good',change:'change'};state.filter=map[m.mode]||'recommended';filterButtons();render();return}if(m.type==='emu-knowledge-open-library'){openPanel('library');return}if(m.type==='emu-knowledge-loading'){if(!m.append)$('#posts').innerHTML=`<section class="card empty"><p>${esc(emuT('k.loadingPosts'))}</p></section>`;return}if(m.type==='emu-knowledge-error'){notify(m.error||emuT('k.toast.loadFailed'));return}if(m.type==='emu-knowledge-prefill'){openComposer();const t=$('#body');if(t){t.value=m.body||'';t.focus();}return}if(m.type==='emu-knowledge-authors'){Object.assign(state.authors,m.authors||{});render();return}if(m.type==='emu-knowledge-posts'){Object.assign(state.authors,m.authors||{});state.posts=m.append?[...state.posts,...m.posts]:m.posts||[];if(!m.append)state.totalCount=(typeof m.totalCount==='number')?m.totalCount:null;state.account=m.account||'';state.monthlyTheme=m.monthlyTheme||'はじめる';state.monthlyCopy=m.monthlyCopy||'';state.drafts=m.drafts||[];state.scheduledCount=m.scheduledCount||0;state.helpedCount=m.helpedCount||0;if(!m.append)state.conclusions=m.conclusions||[];state.canDraft=!!m.canDraft;state.canSchedule=!!m.canSchedule;state.hasMore=!!m.hasMore;state.guestCapped=!!m.guestCapped;state.guestLimit=m.guestLimit||0;$('#draft').hidden=!state.canDraft;$('#schedule').hidden=!state.canSchedule;$('#scheduleField').hidden=!state.canSchedule;themeButtons();render();return}if(m.type==='emu-knowledge-panel-data'){renderPanel(m.kind,m.items||[]);return}if(m.type==='emu-knowledge-save-result'){if(state.pending&&m.requestId===state.pending.requestId)finish(!!m.ok,m.error);if(m.drafts)state.drafts=m.drafts;render();return}if(m.type==='emu-knowledge-drafts'){state.drafts=m.drafts||[];render();if($('#panel').classList.contains('open'))openPanel('library');return}if(m.type==='emu-knowledge-reaction-result'){notify(m.ok?emuT('k.toast.reacted'):m.error||emuT('k.toast.reactFailed'));if(!m.ok)render()}});
